package app.marketlens;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.json.*;

public final class CoreTests {
 static int count;static Path fixtures;
 static void check(boolean ok,String why){count++;if(!ok)throw new AssertionError(why);}
 static void near(double actual,double expected,String why){check(Double.isFinite(actual)&&Math.abs(actual-expected)<Math.max(1e-6,Math.abs(expected)*1e-9),why+" actual="+actual);}
 interface Work {void run()throws Exception;}static void rejects(Work work,String why)throws Exception{boolean caught=false;try{work.run();}catch(Exception e){caught=true;}check(caught,why);}
 static String text(String file)throws Exception{return new String(bytes(file),StandardCharsets.UTF_8);}static byte[] bytes(String file)throws Exception{return Files.readAllBytes(fixtures.resolve(file));}
 public static void main(String[] args)throws Exception{
  fixtures=Paths.get(args[0]);check(Data.isin("INE002A01018"),"Real stock ISIN validates");check(Data.isin("INE040A01034"),"Bank ISIN validates");check(!Data.isin("INE002A01019"),"Bad checksum rejected");check(!Data.isin(""),"Missing ISIN cannot match");check(!Data.isin("RELIANCE"),"Ticker cannot masquerade as ISIN");check(Data.validSymbol("M&M"),"Ampersand symbol allowed");check(!Data.validSymbol("TCS&symbol=INFY"),"Query injection rejected");check(!Data.validSymbol("../TCS"),"Path injection rejected");check(Repository.encoded("M&M").equals("M%26M"),"Symbols are URL encoded");
  near(Parse.number(" 1,234.50 "),1234.5,"Indian number separators parsed");check(Double.isNaN(Parse.number("-")),"Missing value stays missing");check(Double.isNaN(Parse.number("Infinity")),"Infinite values rejected");check(Double.isNaN(Parse.number(JSONObject.NULL)),"JSON null does not become zero");near(Data.position(50,0,100),.5,"Range midpoint");near(Data.position(150,0,100),1,"Range marker clamps");check(Double.isNaN(Data.position(0,0,0)),"Flat range unavailable");check(Double.isNaN(Data.margin(10,0)),"Margin undefined with zero revenue");near(Data.margin(-5,100),-5,"Negative profitability preserved");
  check(Parse.canonical("30-SEP-2026").equals("2026-09-30"),"Exchange dates are case insensitive");check(Parse.canonical("31-Feb-2026").isEmpty(),"Impossible reporting date rejected");check(Parse.canonical("2026-09-30").equals("2026-09-30"),"ISO dates preserved");
  Data.Screen highs=Parse.screen(text("highs.json")),lows=Parse.screen(text("lows.json"));check(!highs.hits.isEmpty()&&!lows.hits.isEmpty(),"Live captured high and low lists parse");check(highs.stamp.equals(new JSONObject(text("highs.json")).getString("timestamp")),"Source time preserved exactly");JSONObject highJson=new JSONObject(text("highs.json"));Set<String> symbols=new HashSet<>();for(String key:new String[]{"dataLtpGreater20","dataLtpLess20"})for(int i=0;i<highJson.getJSONArray(key).length();i++)symbols.add(highJson.getJSONArray(key).getJSONObject(i).getString("symbol"));check(highs.hits.size()==symbols.size(),"Both above/below ₹20 buckets included without duplicates");rejects(()->Parse.screen("{}"),"Wrong screen schema rejected");check(Double.isNaN(Parse.screen("{\"timestamp\":\"2026-11-04\",\"dataLtpGreater20\":[{\"symbol\":\"TCS\"}],\"dataLtpLess20\":[]}").hits.get(0).last),"Absent price is not zero");
  Data.Quote quote=Parse.quote(text("quote.json"),"RELIANCE");near(quote.last,1311,"Official quote price");near(quote.low,1152.2,"Official 52w low");near(quote.high,1611.8,"Official 52w high");near(quote.pe,18.51,"P/E is taken from exchange");near(quote.cap,17741158264542d,"Market cap stored in raw INR");check(quote.stamp.equals("04-Nov-2026 16:00:00"),"Quote exchange timestamp preserved");check(quote.isin.equals("INE002A01018"),"Quote ISIN read");rejects(()->Parse.quote(text("quote.json"),"TCS"),"A different stock cannot be accepted");rejects(()->Parse.quote("{\"equityResponse\":[]}","TCS"),"Empty quote rejected");
  JSONObject filing=Parse.latest(text("financials.json"),"RELIANCE",true);check(Parse.str(filing,"qe_Date").equals("30-SEP-2026"),"Newest financial reporting period selected");check(Parse.str(filing,"consolidated").equals("Consolidated"),"Consolidated preferred within same period");JSONObject reordered=new JSONObject(text("financials.json"));JSONArray data=reordered.getJSONArray("data"),reverse=new JSONArray();for(int i=data.length()-1;i>=0;i--)reverse.put(data.get(i));reordered.put("data",reverse);check(Parse.str(Parse.latest(reordered.toString(),"RELIANCE",true),"xbrl").equals(Parse.str(filing,"xbrl")),"Selection is independent of API sort order");rejects(()->Parse.latest(text("financials.json"),"TCS",true),"Mismatched company filing rejected");
  Data.Financial f=Parse.financial(bytes("financial.xml"),filing);near(f.revenue/1e7,332861,"Revenue INR to crore conversion");near(f.profit/1e7,29550,"Quarterly PAT is not year-to-date PAT");near(f.eps,18.88,"EPS read from same reporting context");check(f.start.equals("2026-07-01")&&f.end.equals("2026-09-30"),"One quarter used consistently");check(f.basis.equals("Consolidated"),"Basis is retained");rejects(()->Parse.financial(text("financial.xml").replace("iso4217:INR","iso4217:USD").getBytes(StandardCharsets.UTF_8),filing),"Non-INR facts are not displayed as rupees");
  JSONObject ownFiling=Parse.latest(text("ownership.json"),"RELIANCE",false);Data.Ownership own=Parse.ownership(bytes("ownership.xml"),ownFiling);near(own.promoter,50.44,"Promoter percentage uses published value");near(own.publicPct,49.56,"Public includes institutions");near(own.mutual,10.31,"XBRL ownership ratio converted to percent");near(own.fundCount,79,"MF holder count parsed independently of named holders");check(own.holders.size()==2,"Only actually named funds displayed");check(own.holders.stream().anyMatch(h->h.name.equals("SBI Mutual Funds")),"Fund name context resolved");check(own.holders.stream().anyMatch(h->h.name.equals("ICICI Prudential Mutual Funds")&&h.shares>0&&h.percent>0),"Typed contexts join name and share facts");check(own.date.equals("2026-09-30"),"Ownership date retained");
  List<Data.Portfolio> portfolios=Xlsx.portfolios(bytes("portfolio.xlsx"),"","2026-09-30","https://amc.ppfas.com/");check(portfolios.size()==1,"Official single-scheme workbook parsed");Data.Portfolio p=portfolios.get(0);check(p.name.equals("Parag Parikh Flexi Cap Fund"),"Actual scheme title extracted");check(p.holdings.size()>20,"Workbook equity holdings extracted");Data.Holding bank=p.holdings.stream().filter(h->h.isin.equals("INE040A01034")).findFirst().get();near(bank.weight,7.75,"Excel percentage format interpreted as 7.75%, not 0.0775%");near(bank.shares,158729224,"Quantity retains whole shares");check(bank.asOf.equals("2026-09-30"),"Monthly reporting date retained");rejects(()->Xlsx.portfolios(bytes("portfolio.xlsx"),"","2026-08-31",""),"Incorrect workbook reporting date rejected");rejects(()->Xlsx.portfolios(new byte[]{1,2,3},"","2026-09-30",""),"Legacy XLS is not silently parsed as XLSX");near(Xlsx.column("AA102"),26,"Multi-letter worksheet columns supported");
  String csv="fund,isin,stock_name,quantity,weight_percent,as_of\r\n\"Fund, One\",INE040A01034,\"HDFC Bank\",100,7.75,2026-09-30\r\nFund Two,INE002A01018,Reliance,200,2.5,2026-09-30";List<Data.Portfolio> imported=Parse.importCsv(csv,"","","");check(imported.size()==2,"Multiple CSV funds remain separate");near(imported.get(0).holdings.get(0).weight,7.75,"CSV weights already in percentage points");check(imported.get(0).name.equals("Fund, One"),"Quoted CSV commas supported");rejects(()->Parse.importCsv(csv.replace("7.75","107.75"),"","",""),"Impossible fund weight rejected");rejects(()->Parse.importCsv(csv.replace("INE040A01034","INE040A01035"),"","",""),"Invalid imported ISIN rejected");rejects(()->Parse.csv("a,b\n\"unfinished"),"Truncated CSV rejected");Data.Portfolio round=Data.Portfolio.from(p.json());check(round.holdings.size()==p.holdings.size()&&round.date.equals(p.date),"Saved portfolio round trip preserves coverage/date");check(Data.Holding.from(new JSONObject("{\"isin\":\"INE002A01018\"}")).shares!=0,"Missing saved quantity remains unavailable");
  check(Net.allowed(Repository.NSE+"/api/x"),"Official NSE allowed");check(Net.allowed("https://nsearchives.nseindia.com/corporate/xbrl/a.xml"),"Official filing archive allowed");check(!Net.allowed("https://www.nseindia.com.evil.example/a"),"Lookalike domain rejected");check(!Net.allowed("https://www.nseindia.com@evil.example/a"),"Credential URL spoof rejected");check(!Net.allowed("http://www.nseindia.com/a"),"Cleartext source rejected");check(!Net.allowed("https://127.0.0.1/a"),"Local host cannot become a download source");rejects(()->Parse.xml("<!DOCTYPE x [<!ENTITY ext SYSTEM 'file:///etc/passwd'>]><x>&ext;</x>".getBytes(StandardCharsets.UTF_8)),"XML external entities rejected");ByteArrayOutputStream archive=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(archive)){zip.putNextEntry(new ZipEntry("../escape.xml"));zip.write(1);zip.closeEntry();}rejects(()->Xlsx.portfolios(archive.toByteArray(),"","2026-09-30",""),"Workbook path traversal rejected");
  List<Data.Stock> catalog=Parse.catalog(text("equities.csv"));check(catalog.size()>2000,"Official symbol catalog parses");check(catalog.stream().anyMatch(s->s.symbol.equals("RELIANCE")&&s.isin.equals("INE002A01018")),"Catalog joins stock to official ISIN");
  for(String symbol:new String[]{"HDFCBANK","SBIN","TCS"}){JSONObject entry=Parse.latest(text(symbol+"-financials.json"),symbol,true);Data.Financial result=Parse.financial(bytes(symbol+"-financial.xml"),entry);check(Double.isFinite(result.revenue)&&Double.isFinite(result.profit)&&Double.isFinite(result.eps),symbol+" current financial taxonomy supported");check(result.end.equals("2026-09-30"),symbol+" newest period preserved");if(symbol.equals("HDFCBANK")){near(result.revenue/1e7,129358.69,"Bank total income INR conversion");near(result.profit/1e7,20700.03,"Bank PAT parsed");near(result.eps,13.43,"Bank EPS after extraordinary items");check(result.revenueLabel.equals("Total income"),"Bank income not relabelled operations revenue");}if(symbol.equals("TCS"))near(result.revenue/1e7,73188,"IT services revenue from operations preferred over total income");}
  System.out.println("Passed "+count+" checks against captured official NSE and AMC files.");
 }
}
